// @zeus-internal
import { GrainGradient, MeshGradient, Swirl } from "@paper-design/shaders-react";
import type { SceneId } from "./data";
interface OffscreenPausingMount {
    intersectionObserver?: IntersectionObserver | null;
    isInViewport?: boolean;
    updateCurrentSpeed?: () => void;
}
type ShaderHost = HTMLElement & {
    paperShaderMount?: OffscreenPausingMount;
};
function keepAnimatingOffscreen(element: HTMLElement | null): (() => void) | undefined {
    if (!element)
        return undefined;
    const host = element as ShaderHost;
    const release = (): boolean => {
        const mount = host.paperShaderMount;
        if (!mount)
            return false;
        mount.intersectionObserver?.disconnect();
        mount.intersectionObserver = null;
        mount.isInViewport = true;
        mount.updateCurrentSpeed?.();
        return true;
    };
    if (release())
        return undefined;
    const observer = new MutationObserver(() => {
        if (release())
            observer.disconnect();
    });
    observer.observe(host, { attributes: true, attributeFilter: ["data-paper-shader"] });
    return () => observer.disconnect();
}
const DIRECTION_COLORS = ["#f8e3cc", "#e9a883", "#d4846f", "#f3c39d"];
const TRUST_COLORS = ["#d9ede2", "#a7cdb8", "#7ea49b", "#e6d9be"];
const IDEA_COLORS = ["#e7eef1", "#afc9d7", "#d7b4a2"];
export function SceneShader({ scene }: {
    scene: SceneId;
}) {
    if (scene === "direction") {
        return (<GrainGradient ref={keepAnimatingOffscreen} className="art:h-full art:w-full" speed={0.12} colorBack="#f3d7bd" colors={DIRECTION_COLORS} softness={0.88} intensity={0.5} noise={0.25} shape="corners"/>);
    }
    if (scene === "trust") {
        return (<MeshGradient ref={keepAnimatingOffscreen} className="art:h-full art:w-full" speed={0.1} colors={TRUST_COLORS} distortion={0.48} swirl={0.3} grainMixer={0} grainOverlay={0}/>);
    }
    return (<Swirl ref={keepAnimatingOffscreen} className="art:h-full art:w-full" speed={0.1} colorBack="#d9e7ef" colors={IDEA_COLORS} bandCount={4} twist={0.1} center={0.2} proportion={0.5} softness={0} noiseFrequency={0.4} noise={0.2}/>);
}

